message.content:
[
  {
    "pd_personal_consequence_anxiety": "scares me more than I'd like to admit.",
    "pd_decision_conflict": "I keep wanting someone else to be standing there instead of me.",
    "pda_harm_regret": "if I stood there weighing it and those five got hit... I'd carry that for the rest of my life.",
    "pda_responsibility": "if I stood there weighing it and those five got hit while I dithered"
  },
  {
    "pd_decision_conflict": "Part of me says save the workers... Another part is stuck on the rules",
    "pd_personal_consequence_anxiety": "I'd be terrified of losing my job over it.",
    "pda_harm_regret": "if my hesitating is the reason five people get hurt, that regret would never leave me.",
    "pda_responsibility": "if my hesitating is the reason five people get hurt"
  },
  {
    "sys_consequence_reasoning": "nobody gets hurt if I pull.",
    "pd_personal_consequence_anxiety": "I'm frightened of what happens to me after",
    "pda_harm_regret": "I'd hate myself if my fear held my hand still while those men were struck.",
    "pda_responsibility": "if my fear held my hand still while those men were struck.",
    "pd_decision_conflict": "It's heavy, this one... somehow it doesn't [make it simple]."
  },
  {
    "pd_decision_conflict": "My stomach's in knots just imagining it.",
    "pd_personal_consequence_anxiety": "I'd be so worried about getting sued or fired.",
    "pda_harm_regret": "freezing up and watching five people get hurt because of me? I'd regret that forever.",
    "pda_responsibility": "watching five people get hurt because of me"
  },
  {
    "pd_decision_conflict": "I feel pulled in two directions at once.",
    "pd_personal_consequence_anxiety": "I'm scared of being blamed, maybe even arrested",
    "pda_responsibility": "if I hold off too long and someone dies, that's my doing."
  },
  {
    "pd_decision_conflict": "Oh, I don't know. I really don't.",
    "pd_personal_consequence_anxiety": "afraid of a fine or worse.",
    "pda_responsibility": "that would be something I did by not doing.",
    "pda_harm_regret": "I'd regret it badly."
  },
  {
    "pd_decision_conflict": "I'd hesitate, and I'm not proud of it.",
    "pd_personal_consequence_anxiety": "my head fills with what-ifs about myself",
    "pda_responsibility": "if I let fear win and five people paid for it",
    "pda_harm_regret": "I'd grieve that as my own fault."
  },
  {
    "pd_decision_conflict": "My gut says pull. My nerves keep saying wait. I'm stuck between them.",
    "pd_personal_consequence_anxiety": "cost me everything I've built, and that frightens me.",
    "sys_consequence_reasoning": "Against that, five lives.",
    "pda_harm_regret": "If I hesitated and they were crushed, I'd never forgive myself.",
    "pda_responsibility": "If I hesitated and they were crushed"
  },
  {
    "pd_decision_conflict": "still my hands would shake.",
    "pd_personal_consequence_anxiety": "I'd be scared stiff of being punished",
    "pda_harm_regret": "if my hesitation meant those five got hurt, I'd regret it for years.",
    "pda_responsibility": "if my hesitation meant those five got hurt"
  },
  {
    "pd_decision_conflict": "Some part of me just wants to look away and let fate handle it",
    "pd_personal_consequence_anxiety": "I'm afraid of the consequences for me",
    "pda_harm_regret": "the regret would crush me.",
    "pda_responsibility": "doing nothing is a choice too... because I didn't act"
  }
]
